"""
Memory Match  -  بازسازی تمرین حافظه‌ی لوموسیتی با پایتون (tkinter)

اجرا:   python memory_match_with_original_audio.py
پوشه‌ی lumosity_original_audio باید کنار این فایل باشد.
در ویندوز پخش WAV با winsound انجام می‌شود و به نصب کتابخانه‌ی صوتی نیاز نیست.

قوانین (از روی ویدیوی بازی):
  * هر بار یک کارت با شکل روی صفحه می‌آید و کارت قبلی پشت‌رو کنارش می‌ماند.
  * اگر کارت فعلی با کارت «بلافاصله قبلی» یکی بود  ->  کلید ←  نه، → بله
  * ۴۵ ثانیه وقت داری.
  * هر پاسخ درست = ۱۰۰ × ضریب.  هر ۴ پاسخ درست پشت‌سرهم ضریب +۱ می‌شود.
  * پاسخ غلط: ضریب -۱ و نقطه‌ها صفر می‌شوند.
  * آخر بازی «Score Bonus» = ضریب × ۲۵۰.

ساختار برنامه (برای یادگیری شی‌گرایی):
  GameLogic  ->  فقط منطق و امتیاز (هیچ گرافیکی ندارد)
  App        ->  پنجره، انیمیشن، کلیدها و کشیدن همه‌چیز روی Canvas
"""
import math
import base64
import io
import tempfile
import zipfile
import os
import random
import shutil
import subprocess
import sys
import time
import tkinter as tk

try:
    import winsound
except ImportError:
    winsound = None

# ====================================================================
#  تنظیمات  (اگر چیزی با بازی اصلی فرق داشت، فقط همین عددها را عوض کن)
# ====================================================================
W, H = 800, 600                 # اندازه‌ی صفحه
GAME_SECONDS = 45               # مدت بازی
POINTS_PER_HIT = 100            # امتیاز پایه‌ی هر پاسخ درست
HITS_PER_LEVEL = 4              # چند پاسخ درست پشت‌سرهم تا ضریب بالا برود
MAX_MULTIPLIER = 10
BONUS_PER_LEVEL = 250           # Score Bonus = ضریب × این عدد
MATCH_CHANCE = 0.5              # احتمال اینکه کارت جدید با کارت قبلی یکی باشد

FIRST_CARD_SECONDS = 1.0        # کارت اول چند ثانیه نشان داده می‌شود
ANIM_SECONDS = 0.22             # مدت چرخیدن کارت
FEEDBACK_SECONDS = 0.35         # مدت نمایش ✓ یا ✗
BONUS_SECONDS = 2.8             # مدت نمایش صفحه‌ی Score Bonus

CARD = 250                      # اندازه‌ی هر کارت
CARD_Y = 175                    # فاصله‌ی کارت‌ها از بالا
LEFT_X = 128                    # جای کارت قبلی (پشت‌رو)
RIGHT_X = 422                   # جای کارت فعلی

SHAPES = ["circle", "triangle", "flower", "square"]
SHAPE_COLORS = {
    "circle": "#4db8b0",        # فیروزه‌ای
    "triangle": "#ffdd00",      # زرد
    "flower": "#96a424",        # سبز زیتونی
    "square": "#d41c4e",        # قرمز
}
QUESTION = "Does the CURRENT card match the card that\ncame IMMEDIATELY BEFORE it?"
TUTORIAL_CARDS = ["flower", "circle", "triangle", "triangle", "square", "square"]
TAG = "dyn"                     # هر چیزی که هر فریم دوباره کشیده می‌شود


# ====================================================================
#  صداهای اصلی استخراج‌شده از فایل‌های Unity بازی
#
#  فایل‌های WAV کنار همین فایل پایتون، داخل پوشه‌ی
#  lumosity_original_audio قرار دارند. این WAVها صدای مصنوعی نیستند؛
#  از داده‌های صوتی داخل cug-shared-assets.bundle استخراج و برای پخش
#  آسان‌تر تبدیل قالب شده‌اند.
# ====================================================================
class SoundManager:
    def __init__(self, root):
        self.root = root
        self.enabled = True
        # ابتدا پوشه‌ی صوتی کنار فایل را پیدا می‌کنیم. اگر کاربر فقط همین فایل
        # پایتون را دانلود کرده باشد، صداهای اصلیِ جاسازی‌شده در خود کد استخراج می‌شوند.
        local_audio_dir = os.path.join(
            os.path.dirname(os.path.abspath(__file__)), "lumosity_original_audio"
        )
        required_audio = ["answerCorrect.wav", "answerWrong.wav", "gameStart.wav", "gameEnd.wav"]
        if os.path.isdir(local_audio_dir) and all(os.path.isfile(os.path.join(local_audio_dir, f)) for f in required_audio):
            self.audio_dir = local_audio_dir
            self.audio_status = "Original audio files found"
        else:
            self.audio_dir = os.path.join(tempfile.gettempdir(), "lumosity_original_audio_embedded")
            try:
                os.makedirs(self.audio_dir, exist_ok=True)
                with zipfile.ZipFile(io.BytesIO(base64.b64decode(EMBEDDED_AUDIO_B64))) as audio_zip:
                    audio_zip.extractall(self.audio_dir)
                if all(os.path.isfile(os.path.join(self.audio_dir, f)) for f in required_audio):
                    self.audio_status = "Original audio embedded and ready"
                else:
                    self.audio_status = "Audio files missing"
            except Exception as exc:
                self.audio_status = "Audio extraction failed: " + str(exc)
        # نام رویدادهای داخل کد را به فایل صوتی اصلی مربوط می‌کنیم.
        self.sound_files = {
            "flip": "cardSlide.wav",
            "card_set": "cardSet.wav",
            "correct": "answerCorrect.wav",
            "correct2": "answerCorrectX2.wav",
            "correct3": "answerCorrectX3.wav",
            "correct4": "answerCorrectX4.wav",
            "wrong": "answerWrong.wav",
            "start": "gameStart.wav",
            "bonus": "counterCount.wav",
            "bonus_end": "counterEnd.wav",
            "end": "gameEnd.wav",
            "countdown": "countdown.wav",
            "timer": "timer.wav",
            "popup_in": "popUpAppear.wav",
            "popup_out": "popUpDisappear.wav",
            "counter_loop": "counterCount_loopable.wav",
        }
        self.files = {
            name: os.path.join(self.audio_dir, filename)
            for name, filename in self.sound_files.items()
        }
        self.current_process = None
        self.last_error = ""

    def play(self, name):
        """پخش یکی از صداهای اصلی؛ مقدار True یعنی درخواست پخش به سیستم ارسال شد."""
        if not self.enabled:
            self.last_error = "Sound is OFF (press M to enable)"
            return False
        path = self.files.get(name)
        if not path or not os.path.isfile(path):
            self.last_error = "Audio file not found: " + str(path)
            return False

        # در ویندوز از پخش‌کننده‌ی داخلی استفاده می‌کنیم؛ WAV نیاز به نصب ندارد.
        if winsound is not None:
            try:
                winsound.PlaySound(
                    path,
                    winsound.SND_FILENAME | winsound.SND_ASYNC
                )
                self.last_error = ""
                return True
            except (RuntimeError, OSError) as exc:
                self.last_error = "winsound failed: " + str(exc)

        # در macOS از afplay و در سیستم‌های دیگر از ffplay، اگر نصب باشند.
        player = None
        if sys.platform == "darwin":
            player = shutil.which("afplay")
            command = [player, path] if player else None
        else:
            player = shutil.which("ffplay")
            command = [player, "-nodisp", "-autoexit", "-loglevel", "quiet", path] if player else None

        if command:
            try:
                if self.current_process and self.current_process.poll() is None:
                    self.current_process.terminate()
                self.current_process = subprocess.Popen(
                    command,
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL
                )
                self.last_error = ""
                return True
            except OSError as exc:
                self.current_process = None
                self.last_error = "Audio player failed: " + str(exc)
        if not command:
            self.last_error = "No compatible audio player found (Windows should use winsound)"
        return False

    def toggle(self):
        self.enabled = not self.enabled
        if not self.enabled and winsound is not None:
            try:
                winsound.PlaySound(None, 0)
            except RuntimeError:
                pass
        if not self.enabled and self.current_process and self.current_process.poll() is None:
            self.current_process.terminate()
        return self.enabled


# ====================================================================
#  منطق بازی (بدون هیچ گرافیکی)
# ====================================================================
class GameLogic:
    def __init__(self):
        self.reset()

    def reset(self):
        self.score = 0
        self.multiplier = 1
        self.streak = 0          # تعداد نقطه‌های پر شده (۰ تا ۳)
        self.correct = 0
        self.total = 0
        self.previous = None     # کارت قبلی (در شروع وجود ندارد)
        self.current = random.choice(SHAPES)

    def _new_card(self):
        """با احتمال MATCH_CHANCE همان شکل قبلی، وگرنه یک شکل دیگر."""
        if self.previous is not None and random.random() < MATCH_CHANCE:
            return self.previous
        others = [s for s in SHAPES if s != self.previous]
        return random.choice(others)

    def advance(self):
        """کارت فعلی می‌شود «قبلی» و کارت تازه می‌آید."""
        self.previous = self.current
        self.current = self._new_card()

    def answer(self, says_match):
        """says_match=True یعنی بازیکن گفت «بله، یکی هستند». درست بود؟ برمی‌گرداند."""
        is_match = (self.current == self.previous)
        is_correct = (says_match == is_match)
        self.total += 1
        if is_correct:
            self.correct += 1
            self.score += POINTS_PER_HIT * self.multiplier
            self.streak += 1
            if self.streak == HITS_PER_LEVEL:
                self.streak = 0
                self.multiplier = min(self.multiplier + 1, MAX_MULTIPLIER)
        else:
            self.streak = 0
            self.multiplier = max(self.multiplier - 1, 1)
        self.advance()
        return is_correct

    def end_bonus(self):
        return self.multiplier * BONUS_PER_LEVEL


# ====================================================================
#  توابع کمکی برای کشیدن
# ====================================================================
def make_background():
    """پس‌زمینه‌ی چوبی آبی با حاشیه‌های تیره (در نیمه‌ی اندازه ساخته و دو برابر می‌شود)."""
    w, h = W // 2, H // 2
    rnd = random.Random(3)
    base = (34, 98, 152)
    grain, g = [], 1.0
    for _ in range(h):                       # رگه‌های افقی چوب
        if rnd.random() < 0.12:
            g = rnd.uniform(0.80, 1.06)
        grain.append(g * (0.72 if rnd.random() < 0.05 else 1.0))
    data = bytearray()
    for y in range(h):
        dy = (y - h / 2) / (h / 2)
        for x in range(w):
            dx = (x - w / 2) / (w / 2)
            v = grain[y] * (1.05 - 0.32 * (dx * dx + dy * dy))
            data += bytes((int(base[0] * v), int(base[1] * v), int(base[2] * v)))
    ppm = b"P6 %d %d 255\n" % (w, h) + bytes(data)
    return tk.PhotoImage(data=ppm, format="PPM").zoom(2, 2)


def rounded_rect(c, x1, y1, x2, y2, r, **options):
    r = max(0, min(r, (x2 - x1) / 2, (y2 - y1) / 2))
    pts = [x1 + r, y1, x2 - r, y1, x2, y1, x2, y1 + r, x2, y2 - r, x2, y2,
           x2 - r, y2, x1 + r, y2, x1, y2, x1, y2 - r, x1, y1 + r, x1, y1]
    return c.create_polygon(pts, smooth=True, **options)


def draw_text(c, x, y, s, size=14, bold=True, color="white", anchor="center"):
    font = ("Helvetica", size, "bold" if bold else "normal")
    c.create_text(x, y, text=s, font=font, fill=color, anchor=anchor,
                  justify="center", tags=TAG)


def draw_shape(c, shape, cx, cy, size, sx=1.0):
    """شکل را وسط (cx, cy) می‌کشد. sx بین 0 و 1 برای حالت چرخیدن کارت است."""
    def X(dx):
        return cx + dx * sx
    k = {"fill": SHAPE_COLORS[shape], "outline": SHAPE_COLORS[shape], "tags": TAG}
    if shape == "circle":
        r = 0.31 * size
        c.create_oval(X(-r), cy - r, X(r), cy + r, **k)
    elif shape == "square":
        r = 0.30 * size
        c.create_rectangle(X(-r), cy - r, X(r), cy + r, **k)
    elif shape == "triangle":
        b, t = 0.34 * size, 0.58 * size
        c.create_polygon(X(0), cy - t * 0.55, X(b), cy + t * 0.45,
                         X(-b), cy + t * 0.45, **k)
    elif shape == "flower":
        d, r = 0.16 * size, 0.105 * size      # فاصله‌ی گلبرگ‌ها و اندازه‌شان
        for i in range(6):
            a = math.radians(60 * i)
            px, py = d * math.cos(a), d * math.sin(a)
            c.create_oval(X(px - r), cy + py - r, X(px + r), cy + py + r, **k)
        c.create_oval(X(-d), cy - d, X(d), cy + d, **k)


def draw_card_face(c, x0, y0, size, shape, sx=1.0):
    """کارت سفید با شکل."""
    cx, half = x0 + size / 2, size / 2 * sx
    if half < 1:
        return
    rounded_rect(c, cx - half + 3, y0 + 5, cx + half + 3, y0 + size + 5, 14,
                 fill="#143f66", outline="", tags=TAG)          # سایه
    rounded_rect(c, cx - half, y0, cx + half, y0 + size, 14,
                 fill="white", outline="", tags=TAG)
    draw_shape(c, shape, cx, y0 + size / 2, size, sx)


def draw_card_back(c, x0, y0, size, sx=1.0):
    """پشت کارت: آبی تیره با الگوی لوزی."""
    cx, half = x0 + size / 2, size / 2 * sx
    if half < 1:
        return
    rounded_rect(c, cx - half, y0, cx + half, y0 + size, 14,
                 fill="#0f4a7c", outline="#0b3a63", width=3, tags=TAG)
    n = 7
    step = size * 0.8 / n
    r = step * 0.45
    for i in range(n):
        for j in range(n):
            mx = cx + (i + 0.5 - n / 2) * step * sx
            my = y0 + size / 2 + (j + 0.5 - n / 2) * step
            c.create_polygon(mx, my - r, mx + r * sx, my, mx, my + r,
                             mx - r * sx, my, fill="", outline="#0c4170", tags=TAG)


def draw_empty_slot(c, x0, y0, size):
    rounded_rect(c, x0, y0, x0 + size, y0 + size, 14,
                 fill="#1c5384", outline="", tags=TAG)


def draw_feedback(c, ok, cx, cy):
    """✓ سبز یا ✗ قرمز."""
    if ok:
        c.create_line(cx - 14, cy, cx - 4, cy + 11, cx + 16, cy - 14, fill="#6cc04a",
                      width=8, capstyle="round", joinstyle="round", tags=TAG)
    else:
        for a, b in ((-1, -1), (-1, 1)):
            c.create_line(cx + 13 * a, cy + 13 * b, cx - 13 * a, cy - 13 * b,
                          fill="#e5484d", width=8, capstyle="round", tags=TAG)


def draw_key(c, cx, cy, direction, active=True):
    """یک کلید جهت‌نما."""
    rounded_rect(c, cx - 13, cy - 13, cx + 13, cy + 13, 4,
                 fill="#f2f6fa" if active else "#5d89ad", outline="", tags=TAG)
    arrows = {
        "left": [cx + 5, cy - 7, cx - 6, cy, cx + 5, cy + 7],
        "right": [cx - 5, cy - 7, cx + 6, cy, cx - 5, cy + 7],
        "up": [cx - 7, cy + 5, cx, cy - 6, cx + 7, cy + 5],
        "down": [cx - 7, cy - 5, cx, cy + 6, cx + 7, cy - 5],
    }
    c.create_polygon(arrows[direction], fill="#1d4f7c" if active else "#3e6d94",
                     outline="", tags=TAG)


def draw_hud(c, time_left, logic):
    """نوار بالا سمت راست: زمان | امتیاز | نقطه‌ها و ضریب."""
    c.create_rectangle(404, 0, W, 38, fill="#5f93bd", outline="", tags=TAG)
    for x in (512, 662):
        c.create_line(x, 6, x, 32, fill="#8fb3d1", tags=TAG)
    secs = max(0, math.ceil(time_left))
    draw_text(c, 458, 19, f"TIME  {secs // 60}:{secs % 60:02d}", 10)
    draw_text(c, 587, 19, f"SCORE  {logic.score}", 10)
    for i in range(HITS_PER_LEVEL):
        filled = i < logic.streak
        c.create_oval(676 + i * 16, 14, 686 + i * 16, 24, outline="",
                      fill="#0d3b66" if filled else "#a9c4da", tags=TAG)
    draw_text(c, 764, 19, f"x{logic.multiplier}", 10)


def draw_answer_bar(c):
    """پایین صفحه:  NO [←] | [→] YES"""
    c.create_rectangle(276, 536, 528, H, fill="#6a9cc4", outline="", tags=TAG)
    c.create_line(402, 540, 402, H - 4, fill="#8fb3d1", tags=TAG)
    draw_text(c, 318, 568, "NO", 11)
    draw_key(c, 364, 568, "left")
    draw_key(c, 440, 568, "right")
    draw_text(c, 488, 568, "YES", 11)


def draw_key_hint(c):
    """راهنمای چهار کلید جهت‌نما (در آموزش)."""
    draw_text(c, 330, 566, "NO", 11)
    draw_key(c, 396, 534, "up", False)
    draw_key(c, 365, 566, "left")
    draw_key(c, 396, 566, "down", False)
    draw_key(c, 427, 566, "right")
    draw_text(c, 470, 566, "YES", 11)


# ====================================================================
#  برنامه‌ی اصلی
# ====================================================================
class App:
    def __init__(self):
        self.root = tk.Tk()
        self.root.title("Memory Match")
        self.root.resizable(False, False)
        self.canvas = tk.Canvas(self.root, width=W, height=H,
                                highlightthickness=0, bg="#226298")
        self.canvas.pack()
        self.bg_image = make_background()      # باید در متغیر بماند، وگرنه tkinter پاکش می‌کند
        self.canvas.create_image(0, 0, image=self.bg_image, anchor="nw", tags="bg")

        self.sound = SoundManager(self.root)
        self.logic = GameLogic()
        self.state = "intro"       # intro -> tutorial -> play -> bonus -> end
        self.paused = False
        self.time_left = GAME_SECONDS
        self.first_delay = None    # تا کارت اول نچرخیده عددی است، بعدش None
        self.bonus_timer = 0.0
        self.bonus_value = 0

        # چیزهایی که روی میز دیده می‌شوند
        self.has_prev = False      # آیا کارت پشت‌رو سمت چپ هست؟
        self.cur_shape = self.logic.current
        self.anim = None           # انیمیشن چرخیدن کارت
        self.feedback = None       # ✓ یا ✗
        self.tut_i = 0
        self.tut_msg = ""

        self.root.bind_all("<Key>", self.on_key)
        self.canvas.bind("<Button-1>", self.on_click)
        self.last = time.monotonic()
        self.tick()

    def run(self):
        self.root.mainloop()

    # ------------------------------------------------------ حلقه‌ی اصلی
    def tick(self):
        now = time.monotonic()
        dt = min(now - self.last, 0.1)
        self.last = now
        self.update(dt)
        self.draw()
        self.root.after(16, self.tick)      # حدود ۶۰ فریم در ثانیه

    def update(self, dt):
        # In gameplay, pausing freezes the whole visible game state, including
        # card flips and answer feedback. Tutorial/bonus animations keep running.
        if self.state != "play" or not self.paused:
            if self.anim:
                self.anim["t"] += dt / ANIM_SECONDS
                if self.anim["t"] >= 1:
                    self.anim = None
            if self.feedback:
                self.feedback["t"] += dt
                if self.feedback["t"] > FEEDBACK_SECONDS:
                    self.feedback = None

        if self.state == "play" and not self.paused:
            self.time_left -= dt
            if self.first_delay is not None:           # کارت اول خودش می‌چرخد
                self.first_delay -= dt
                if self.first_delay <= 0:
                    self.first_delay = None
                    self.logic.advance()
                    self.sound.play("flip")
                    self.flip_to(self.logic.current)
            if self.time_left <= 0:
                self.time_left = 0
                self.bonus_value = self.logic.end_bonus()
                self.bonus_timer = BONUS_SECONDS
                self.state = "bonus"
                self.sound.play("bonus")
        elif self.state == "bonus":
            self.bonus_timer -= dt
            if self.bonus_timer <= 0:
                self.logic.score += self.bonus_value
                self.state = "end"
                self.sound.play("end")

    # ------------------------------------------------------ ورودی
    def on_key(self, event):
        key = event.keysym
        if key == "Escape":
            self.root.destroy()
        elif key in ("Left", "Right"):
            says_match = (key == "Right")
            if self.state == "intro":
                self.start_tutorial()
            elif self.state == "tutorial":
                self.tutorial_answer(says_match)
            elif self.state == "play":
                self.play_answer(says_match)
        elif key.lower() == "m":
            self.sound.toggle()
            self.root.title("Memory Match - " + ("Sound ON" if self.sound.enabled else "Sound OFF"))
        elif key.lower() == "t":
            # تست مستقل صدا؛ در صفحه‌ی شروع هم قابل اجراست.
            played = self.sound.play("start")
            if played:
                self.root.title("Memory Match - Sound test played")
            else:
                self.root.title("Memory Match - SOUND ERROR: " + self.sound.last_error)
        elif key.lower() in ("p", "space") and self.state == "play":
            self.paused = not self.paused
        elif key == "Return" and self.state == "end":
            self.start_game()

    def on_click(self, event):
        if self.state == "tutorial" and event.x < 150 and event.y < 50:
            self.start_game()                                  # Skip tutorial
        elif self.state == "play" and (self.paused or (event.x < 44 and event.y < 44)):
            self.paused = not self.paused

    # ------------------------------------------------------ حالت‌ها
    def can_answer(self):
        """تا پایان کامل انیمیشن کارت، پاسخ تازه پذیرفته نمی‌شود."""
        return self.anim is None

    def flip_to(self, new_shape):
        """کارت فعلی می‌چرخد و می‌رود سمت چپ؛ کارت تازه می‌آید."""
        self.anim = {"t": 0.0, "moving": self.cur_shape, "had_prev": self.has_prev}
        self.has_prev = True
        self.cur_shape = new_shape

    def start_tutorial(self):
        self.state = "tutorial"
        self.tut_i = 0
        self.has_prev = False
        self.cur_shape = TUTORIAL_CARDS[0]
        self.anim = self.feedback = None
        self.tut_msg = "This is the first card. Press either arrow key to flip it."

    def tutorial_answer(self, says_match):
        if not self.can_answer():
            return
        i = self.tut_i
        if i > 0:
            ok = (says_match == (TUTORIAL_CARDS[i] == TUTORIAL_CARDS[i - 1]))
            self.feedback = {"ok": ok, "t": 0.0}
            self.sound.play("correct" if ok else "wrong")
            if not ok:
                self.tut_msg = "Not quite. Same shape = YES (right), different = NO (left)."
                return
        if i == len(TUTORIAL_CARDS) - 1:
            self.start_game()
            return
        self.tut_i += 1
        self.tut_msg = "Same shape = YES (right arrow).  Different shape = NO (left arrow)."
        self.flip_to(TUTORIAL_CARDS[self.tut_i])

    def start_game(self):
        self.logic.reset()
        self.state = "play"
        self.paused = False
        self.time_left = GAME_SECONDS
        self.first_delay = FIRST_CARD_SECONDS
        self.has_prev = False
        self.cur_shape = self.logic.current
        self.anim = self.feedback = None
        self.sound.play("start")

    def play_answer(self, says_match):
        if self.paused or self.first_delay is not None or not self.can_answer():
            return
        multiplier_before = self.logic.multiplier
        correct = self.logic.answer(says_match)
        self.feedback = {"ok": correct, "t": 0.0}
        if correct:
            # نسخه‌های X2 تا X4 صداهای اصلی بازی برای ضریب‌های بالاترند.
            sound_name = "correct" if multiplier_before <= 1 else f"correct{min(multiplier_before, 4)}"
            self.sound.play(sound_name)
        else:
            self.sound.play("wrong")
        self.flip_to(self.logic.current)

    # ------------------------------------------------------ کشیدن
    def draw(self):
        c = self.canvas
        c.delete(TAG)
        if self.state == "intro":
            self.draw_intro()
        elif self.state == "tutorial":
            self.draw_question()
            self.draw_table()
            draw_text(c, W / 2, 470, self.tut_msg, 13, False, "#d6e6f5")
            draw_key_hint(c)
            rounded_rect(c, 14, 14, 138, 38, 12, fill="#12395f", outline="", tags=TAG)
            draw_text(c, 76, 26, "Skip tutorial", 10)
        elif self.state == "play":
            draw_hud(c, self.time_left, self.logic)
            self.draw_question()
            self.draw_table()
            draw_answer_bar(c)
            rounded_rect(c, 0, 0, 42, 42, 4, fill="#2d6a9a", outline="", tags=TAG)
            c.create_rectangle(14, 12, 19, 30, fill="white", outline="", tags=TAG)
            c.create_rectangle(24, 12, 29, 30, fill="white", outline="", tags=TAG)
            draw_text(c, 56, 21, "SOUND ON" if self.sound.enabled else "SOUND OFF", 8, False, "white", "w")
            if self.paused:
                c.create_rectangle(0, 0, W, H, fill="#184d7a", outline="", tags=TAG)
                draw_text(c, W / 2, H / 2 - 16, "PAUSED", 28)
                draw_text(c, W / 2, H / 2 + 28, "Press P or click to continue", 14, False)
        elif self.state == "bonus":
            draw_hud(c, 0, self.logic)
            c.create_oval(W / 2 - 32, 200, W / 2 + 32, 264, fill="#c9d6e2",
                          outline="", tags=TAG)
            draw_text(c, W / 2, 232, f"x{self.logic.multiplier}", 18, True, "#1d4f7c")
            draw_text(c, W / 2, 310, "Score Bonus", 24)
            draw_text(c, W / 2, 348, str(self.bonus_value), 20, False)
        elif self.state == "end":
            self.draw_end()

    def draw_question(self):
        draw_text(self.canvas, W / 2, 128, QUESTION, 16, False)

    def draw_table(self):
        """کارت قبلی (چپ)، کارت فعلی (راست) و انیمیشن چرخیدن."""
        c = self.canvas
        a = self.anim
        if a:
            if a["had_prev"]:
                draw_card_back(c, LEFT_X, CARD_Y, CARD)
            else:
                draw_empty_slot(c, LEFT_X, CARD_Y, CARD)
            t = min(a["t"], 1.0)
            p = t * t * (3 - 2 * t)                       # حرکت نرم
            x0 = LEFT_X + (RIGHT_X - LEFT_X) * (1 - p)
            sx = abs(math.cos(math.pi * p))               # باریک و پهن شدن = چرخیدن
            if p < 0.5:
                draw_card_face(c, x0, CARD_Y, CARD, a["moving"], sx)
            else:
                draw_card_back(c, x0, CARD_Y, CARD, sx)
            if t >= 0.5:
                draw_card_face(c, RIGHT_X, CARD_Y, CARD, self.cur_shape)
        else:
            if self.has_prev:
                draw_card_back(c, LEFT_X, CARD_Y, CARD)
            else:
                draw_empty_slot(c, LEFT_X, CARD_Y, CARD)
            draw_card_face(c, RIGHT_X, CARD_Y, CARD, self.cur_shape)
        if self.feedback:
            draw_feedback(c, self.feedback["ok"], W / 2 - 1, CARD_Y + CARD / 2)

    def draw_intro(self):
        c = self.canvas
        rounded_rect(c, 140, 120, 660, 320, 16, fill="#12395f", outline="#0b2943",
                     width=3, tags=TAG)
        for row in range(5):
            for col in range(14):
                x, y = 160 + col * 24, 140 + row * 30
                c.create_rectangle(x, y, x + 20, y + 24, fill="#1d4f80",
                                   outline="", tags=TAG)
        draw_key(c, 580, 255, "up", False)
        draw_key(c, 550, 287, "left")
        draw_key(c, 580, 287, "down", False)
        draw_key(c, 610, 287, "right")
        draw_text(c, W / 2, 400, "This game uses your keyboard ARROW KEYS", 16, False)
        draw_text(c, W / 2, 470, "Press LEFT or RIGHT ARROW KEY to continue", 16, False)
        draw_text(c, W / 2, 505, "M: sound ON/OFF    |    T: test original sound", 11, False, "#d6e6f5")
        draw_text(c, W / 2, 528, self.sound.audio_status, 9, False, "#d6e6f5")

    def draw_end(self):
        c = self.canvas
        lg = self.logic
        accuracy = round(100 * lg.correct / lg.total) if lg.total else 0
        draw_text(c, W / 2, 190, "Time's up!", 30)
        draw_text(c, W / 2, 270, "FINAL SCORE", 13, False, "#cfe3f5")
        draw_text(c, W / 2, 310, str(lg.score), 40)
        draw_text(c, W / 2, 380, f"Correct answers: {lg.correct} / {lg.total}   ({accuracy}%)",
                  15, False)
        draw_text(c, W / 2, 470, "Press ENTER to play again   |   ESC to quit", 14, False,
                  "#cfe3f5")




